{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "In seven patients, tetrabenazine had a mean oral systemic availability of 0.049 ± 0.032, far below the 20% threshold, indicating extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Almorexant, which shares the dimethoxyphenyl/amide and basic amine features, had an absolute oral bioavailability of 11.2% (90% CI 9.6–13.1) in healthy subjects, below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Donepezil, a dimethoxybenzene-containing basic amine drug, has an oral bioavailability of about 99% in humans, demonstrating that this class can be well absorbed.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "Valbenazine, a tetrabenazine analogue with a prodrug ester, has an absolute oral bioavailability of approximately 49% in humans, showing that structural modification can raise F above 20%.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C23"],
      "claim": "In normal subjects, (+)-verapamil has a mean absolute bioavailability of about 50%, while (-)-verapamil is around 20%, placing racemic verapamil near the threshold; this is weakly contradictory to a low prediction.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The closest analogue tetrabenazine has very low oral bioavailability (mean ~5%), and almorexant, sharing the amide/dimethoxyphenyl motif, has ~11% F; these low-F data outweigh the less similar high-F analogues donepezil and valbenazine. The query's large size, basic amine, and low neutral fraction further support absorption and first-pass metabolism limitations.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "Morgan similarities are moderate (0.25–0.37), limiting transferability.",
    "Valbenazine's high F is from a prodrug ester, not directly comparable to the query's amide/tertiary amine system.",
    "No permeability or metabolic stability data are available for the query."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
