    },
    {
      "applicability": "moderate",
      "card_ids": ["C33"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "almorexant"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C13"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "donepezil"
    },
    {
      "applicability": "low",
      "card_ids": ["C15"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "valbenazine"
    },
    {
      "applicability": "low",
      "card_ids": ["C23"],
      "decision_effect": "no_change",
      "direction": "neutral_or_unclear",
      "family": "verapamil"
    }
  ],
  "revision_action": "initial"
}

